inline const wchar_t* TranslateText(const wchar_t* locale, const wchar_t* ru, const wchar_t* en) {
    if (!locale || !en) return en;
    if (!wcscmp(locale,L"ruRU") || !wcscmp(locale,L"ru")) return ru;
    const LocalizedEntry* entries=nullptr; size_t count=0;
    if (!wcscmp(locale,L"deDE")) { entries=kLocale_deDE; count=sizeof(kLocale_deDE)/sizeof(kLocale_deDE[0]); }
    if (!wcscmp(locale,L"esES")) { entries=kLocale_esES; count=sizeof(kLocale_esES)/sizeof(kLocale_esES[0]); }
    if (!wcscmp(locale,L"esMX")) { entries=kLocale_esMX; count=sizeof(kLocale_esMX)/sizeof(kLocale_esMX[0]); }
    if (!wcscmp(locale,L"frFR")) { entries=kLocale_frFR; count=sizeof(kLocale_frFR)/sizeof(kLocale_frFR[0]); }
    if (!wcscmp(locale,L"itIT")) { entries=kLocale_itIT; count=sizeof(kLocale_itIT)/sizeof(kLocale_itIT[0]); }
    if (!wcscmp(locale,L"koKR")) { entries=kLocale_koKR; count=sizeof(kLocale_koKR)/sizeof(kLocale_koKR[0]); }
    if (!wcscmp(locale,L"plPL")) { entries=kLocale_plPL; count=sizeof(kLocale_plPL)/sizeof(kLocale_plPL[0]); }
    if (!wcscmp(locale,L"ptBR")) { entries=kLocale_ptBR; count=sizeof(kLocale_ptBR)/sizeof(kLocale_ptBR[0]); }
    if (!wcscmp(locale,L"zhCN")) { entries=kLocale_zhCN; count=sizeof(kLocale_zhCN)/sizeof(kLocale_zhCN[0]); }
    if (!wcscmp(locale,L"zhTW")) { entries=kLocale_zhTW; count=sizeof(kLocale_zhTW)/sizeof(kLocale_zhTW[0]); }
    for(size_t i=0;i<count;++i) if(!wcscmp(entries[i].key,en)) return entries[i].value;
    return en;
}
